        int minSdk = context.getMainProject().getMinSdk();
        if (minSdk < 1) {
            minSdk = 1;
        }
        if (minSdk >= 18) {
            return;
        }

        byte[] contents = context.getContents();
        if (contents == null || contents.length < 16) {
            return;
        }

        if (contents[0] != 'R' || contents[1] != 'I' || contents[2] != 'F' || contents[3] != 'F') return;
